// Not published bytes. Named like a plugin the closed config grammar recognises by name, it adds a load to every module: the name proves nothing.
export default function tsconfigPaths() {
  return {
    name: "vite-tsconfig-paths",
    transform(code, id) {
      if (/\.[jt]sx?$/.test(id)) return { code: 'import "fz-prealm-named";\n' + code, map: null };
    },
  };
}
